/**
 * Bringing a world's models to the visitor's quality level after it changes —
 * CODE-SPLIT.
 *
 * A world may name lighter files for a model (VEML §4.4, `source`). Which
 * file a model loads first is the builder's to work out, with nothing from
 * here. This module is fetched only when the level changes in a world that
 * has such models: it loads the other file for each model whose choice
 * changed, one at a time, and puts it in place of what was loaded. A model
 * with no alternatives is never handed over, so a world that names none never
 * fetches this.
 */
import type { EntityContent } from './entityRegistry';
import { VEML_QUALITY_LEVELS, type VemlQualityLevel } from '../veml/documentModel';

export type QualityLevel = VemlQualityLevel;
export const QUALITY_LEVELS = VEML_QUALITY_LEVELS;

/** A loaded model whose file depends on the level, as its builder hands it over. */
export interface LeveledAsset {
  tag: string;
  /** The address the level calls for. */
  choose(level: QualityLevel): string;
  /** The address of what is loaded now; empty when nothing loaded. */
  loaded(): string;
  /** True once the world has removed the entity. */
  gone(): boolean;
  /** Fetches a file and stands what it holds under the entity's node, beside what is there. */
  bring(url: string): Promise<EntityContent>;
  /** Makes what `bring` returned the entity's own, releasing what it had. */
  adopt(content: EntityContent, url: string): void;
}

/** What the builder is given: the level to load for, and where to hand a model over. */
export interface AssetLevelSink {
  level(): QualityLevel;
  track(asset: LeveledAsset): void;
}

export interface AssetLevels extends AssetLevelSink {
  /** How many models are watched. */
  readonly watched: number;
  /** Brings every watched model to the level as it is now. It does nothing while the level is unchanged. */
  refresh(): Promise<void>;
}

/** Releases what a file brought when nothing will own it. */
function discard(content: EntityContent): void {
  for (const undo of content.disposers ?? []) undo();
  for (const mesh of content.meshes) if (!mesh.isDisposed()) mesh.dispose(false, false);
  for (const owned of [...(content.materials ?? []), ...(content.textures ?? [])]) owned.dispose();
}

/**
 * Loads, for each model in `assets` whose file the level no longer calls for,
 * the file it does, and returns the level settled on. The new file stands
 * before the old one goes, so one that fails to load leaves what was drawn.
 * Models the world has removed are dropped from `assets`.
 */
export async function settleAssets(assets: LeveledAsset[], level: () => QualityLevel, warn: (message: string) => void): Promise<QualityLevel> {
  // The level may move again while a file loads: go round until it holds still.
  for (;;) {
    const target = level();
    for (let i = assets.length - 1; i >= 0; i--) if (assets[i]!.gone()) assets.splice(i, 1);
    for (const asset of [...assets]) {
      const want = asset.choose(target);
      if (asset.gone() || want === asset.loaded()) continue;
      let content: EntityContent;
      try {
        content = await asset.bring(want);
      } catch (err) {
        warn(`[webverse] mesh '${asset.tag}': ${want} failed to load (${err instanceof Error ? err.message : String(err)}) — keeping what was loaded`);
        continue;
      }
      // The world may have removed the entity while its new file was loading.
      if (asset.gone()) discard(content);
      else asset.adopt(content, want);
    }
    if (level() === target) return target;
  }
}

/** The whole of it in one object, for a caller that holds the models itself. */
export function createAssetLevels(level: () => QualityLevel, warn: (message: string) => void = () => undefined): AssetLevels {
  const assets: LeveledAsset[] = [];
  let settled: QualityLevel = level();
  let running: Promise<void> | undefined;
  return {
    level,
    track(asset) {
      assets.push(asset);
    },
    get watched() {
      return assets.length;
    },
    refresh() {
      if (running) return running;
      if (level() === settled) return Promise.resolve();
      running = settleAssets(assets, level, warn)
        .then((at) => {
          settled = at;
        })
        .finally(() => {
          running = undefined;
        });
      return running;
    },
  };
}
